  Object.assign(I18N_FA, {"A little daily ritual": "یک رسم کوچک روزانه", "One small challenge, every day.": "هر روز یک چالش کوچک.", "Earn XP by clearing a level for the first time, finishing a daily puzzle, completing a lesson or finishing a board-game match.": "با تکمیل نخستین‌بارهٔ هر مرحله، حل معمای روزانه، پاسخ درست به هر درس و پایان یک مسابقه رومیزی XP بگیرید.", "You completed a lap and received the start bonus.": "یک دور کامل کردید و پاداش شروع را گرفتید."});

  const XP_STEPS = [0, 100, 250, 500, 850, 1300, 1900, 2700, 3700, 5000];
  const XP_RANKS = ['Seedling', 'Explorer', 'Strategist', 'Scholar', 'Expert', 'Master', 'Sage', 'Legend', 'Legend', 'Legend'];

  function getXpProgress(total) {
    let index = 0;
    for (let i = 0; i < XP_STEPS.length; i++) if (total >= XP_STEPS[i]) index = i;
    if (index >= XP_STEPS.length - 1) return { percent: 100, remaining: 0, rank: 'Legend' };
    const low = XP_STEPS[index];
    const high = XP_STEPS[index + 1];
    return {
      percent: Math.max(0, Math.min(100, Math.floor(((total - low) / (high - low)) * 100))),
      remaining: high - total,
      rank: XP_RANKS[index]
    };
  }

  const BG_SPACES = [
    { type: 'start', name: 'Start', icon: '🏁' },
    { type: 'property', name: 'Science', icon: '🔬', career: 'Science' },
    { type: 'property', name: 'Arts', icon: '🎨', career: 'Arts' },
    { type: 'individual', name: 'Individual mission', icon: '🎯' },
    { type: 'property', name: 'Sports', icon: '⚽', career: 'Sports' },
    { type: 'election', name: 'Election', icon: '🗳️' },
    { type: 'property', name: 'Health', icon: '🩺', career: 'Health' },
    { type: 'powerset', name: 'Group mission', icon: '🧩' },
    { type: 'property', name: 'Technology', icon: '💻', career: 'Technology' },
    { type: 'cardinality', name: 'Cardinality', icon: '🔢' },
    { type: 'property', name: 'Music', icon: '🎵', career: 'Music' },
    { type: 'election', name: 'Election', icon: '🗳️' },
    { type: 'individual', name: 'Individual mission', icon: '🎯' },
    { type: 'property', name: 'Science', icon: '🔬', career: 'Science' },
    { type: 'powerset', name: 'Group mission', icon: '🧩' },
    { type: 'rest', name: 'Rest', icon: '🌿' }
  ];
  const BG_CARD_DECK = [
    { name: 'Mina', career: 'Science', value: 4 }, { name: 'Arman', career: 'Science', value: 3 },
    { name: 'Nika', career: 'Arts', value: 5 }, { name: 'Raha', career: 'Arts', value: 4 },
    { name: 'Kian', career: 'Sports', value: 4 }, { name: 'Dara', career: 'Sports', value: 3 },
    { name: 'Laleh', career: 'Health', value: 5 }, { name: 'Omid', career: 'Health', value: 4 },
    { name: 'Tara', career: 'Technology', value: 5 }, { name: 'Sina', career: 'Technology', value: 4 },
    { name: 'Ava', career: 'Music', value: 4 }, { name: 'Navid', career: 'Music', value: 3 }
  ];
  const BG_SUBSETS = ['∅', '{Mina}', '{Omid}', '{Mina, Omid}'];
  const BG_COORDS = [[1,1],[1,2],[1,3],[1,4],[1,5],[2,5],[3,5],[4,5],[5,5],[5,4],[5,3],[5,2],[5,1],[4,1],[3,1],[2,1]];
  let bgCardSequence = 1;
  let lessonIndex = 0;
  let selectedLessonAnswer = null;

  function makeBgCard() {
    const base = BG_CARD_DECK[Math.floor(Math.random() * BG_CARD_DECK.length)];
    return { ...base, id: bgCardSequence++ };
  }

  function makeBgPlayer(id, name, human = false) {
    const player = {
      id, name, human, position: 0, points: 0, cards: [],
      missionTargets: human ? ['Mina', 'Omid'] : id === 1 ? ['Nika', 'Kian'] : ['Tara', 'Laleh'],
      missions: 0
    };
    const starterDeck = [...BG_CARD_DECK].sort(() => Math.random() - 0.5);
    starterDeck.slice(0, 4).forEach(card => player.cards.push({ ...card, id: bgCardSequence++ }));
    return player;
  }

  function createBoardGame() {
    bgCardSequence = 1;
    return {
      players: [makeBgPlayer(0, 'You', true), makeBgPlayer(1, 'Bot 1'), makeBgPlayer(2, 'Bot 2')],
      properties: {}, round: 1, maxRounds: 8, phase: 'roll', pendingSpace: null,
      lastRoll: null, history: [], powerSetChoices: [], finished: false, xpAwarded: false, lastResult: ''
    };
  }

  function loadBoardGame() {
    try {
      const saved = JSON.parse(localStorage.getItem('mosaic-boardgame-v1') || 'null');
      if (saved && Array.isArray(saved.players) && saved.players.length === 3 && saved.players.every(p => Array.isArray(p.cards))) {
        bgCardSequence = Math.max(1, ...saved.players.flatMap(p => p.cards.map(c => Number(c.id) + 1 || 1)));
        return saved;
      }
    } catch {}
    return createBoardGame();
  }

  let boardGameState = loadBoardGame();
  const bgSave = () => { try { localStorage.setItem('mosaic-boardgame-v1', JSON.stringify(boardGameState)); } catch {} };
  const tr = key => (typeof language !== 'undefined' && language === 'fa' ? (I18N_FA[key] || key) : key);
  const bgPlayer = () => boardGameState.players[0];
  const bgPropertyOwner = index => boardGameState.properties[index] === undefined ? null : boardGameState.players[boardGameState.properties[index]];
  const bgCardCount = (player, career) => player.cards.filter(card => card.career === career).length;
  const bgAddCard = (player, card) => {
    if (player.cards.some(existing => existing.name === card.name)) return false;
    player.cards.push({ ...card, id: bgCardSequence++ });
    return true;
  };
  const bgDrawCards = (player, career = null, amount = 1) => {
    const available = (career ? BG_CARD_DECK.filter(c => c.career === career) : BG_CARD_DECK)
      .filter(card => !player.cards.some(existing => existing.name === card.name));
    let drawn = 0;
    for (let i = 0; i < amount && available.length; i++) {
      const index = Math.floor(Math.random() * available.length);
      const [card] = available.splice(index, 1);
      if (bgAddCard(player, card)) drawn++;
    }
    return drawn;
  };
  const bgLog = message => {
    boardGameState.history.unshift(message);
    boardGameState.history = boardGameState.history.slice(0, 5);
  };

  function renderBoardGame() {
    if (!$('boardGameView')) return;
    const bg = boardGameState;
    const human = bgPlayer();
    const spaces = BG_SPACES.map((space, index) => {
      const [row, col] = BG_COORDS[index];
      const owner = bgPropertyOwner(index);
      const tokens = bg.players.filter(p => p.position === index).map(p => `<i class="bg-token ${p.human ? 'human' : 'bot'}" title="${tr(p.name)}">${p.human ? 'S' : p.id}</i>`).join('');
      return `<div class="bg-space ${space.type}" data-index="${index}" style="grid-row:${row};grid-column:${col}"><span class="bg-space-icon">${space.icon}</span><b>${tr(space.name)}</b>${owner ? `<small>${tr(owner.name)}</small>` : ''}<span class="bg-tokens">${tokens}</span></div>`;
    }).join('');
    $('boardTrack').innerHTML = `${spaces}<div class="board-center"><div class="board-center-mark"><span class="mosaic-mark"><i></i><i></i><i></i><i></i></span><b>Setarea</b></div><p>${tr('Round')} ${bg.round} ${tr('of')} ${bg.maxRounds}</p><small>${tr('Collect cards · Complete missions · Build sets')}</small></div>`;
    $('boardGameRound').textContent = `${tr('Round')} ${bg.round} ${tr('of')} ${bg.maxRounds}`;
    $('boardGameLastRoll').textContent = bg.lastRoll === null ? tr('🎲 Roll the dice to begin') : `${tr('You rolled')} ${bg.lastRoll}`;
    $('boardGameTurnStatus').textContent = bg.phase === 'finished' ? tr('Match complete') : bg.phase === 'roll' ? tr('Your turn') : bg.phase === 'action' ? tr('Choose an action') : bg.phase === 'end' ? tr('Action complete') : tr('Your turn');
    $('boardGamePlayers').innerHTML = bg.players.map(p => `<div class="bg-player ${p.human ? 'current' : ''}"><span class="bg-player-token ${p.human ? 'human' : ''}">${p.human ? 'S' : p.id}</span><div class="bg-player-info"><b>${tr(p.name)}</b><small>${p.cards.length} ${tr('cards')} · ${p.missions} ${tr('missions')}</small></div><strong>${p.points} ${tr('points')}</strong></div>`).join('');
    $('boardGameHand').innerHTML = human.cards.length ? human.cards.map(card => `<div class="bg-card"><b>${card.name}</b><small>${tr(card.career)}</small><span>✦ ${card.value}</span></div>`).join('') : `<p>${tr('Your hand is empty.')}</p>`;
    $('boardGameCardCount').textContent = `${human.cards.length} ${tr('cards')}`;
    $('boardGameLog').innerHTML = bg.history.length ? bg.history.map(item => `<p>${item}</p>`).join('') : `<p>${tr('No events yet. Your first move starts the game.')}</p>`;
    $('boardGameAction').innerHTML = renderBoardAction();
  }

  function renderBoardAction() {
    const bg = boardGameState;
    const space = bg.pendingSpace === null ? null : BG_SPACES[bg.pendingSpace];
    if (bg.phase === 'finished') {
      return `<span class="eyebrow">${tr('MATCH COMPLETE')}</span><h2>${tr('Match complete')}</h2><p>${bg.lastResult}</p><button class="primary-button" data-bg="new">${tr('New match')}</button>`;
    }
    if (bg.phase === 'roll') {
      return `<span class="eyebrow">${tr('YOUR TURN')}</span><h2>${tr('Roll the dice to move around the board.')}</h2><p>${tr('Roll the dice to begin your turn. The space you land on determines your mission.')}</p><button class="primary-button" data-bg="roll">🎲 ${tr('Roll dice')}</button>`;
    }
    if (bg.phase === 'end') {
      return `<span class="eyebrow">${tr('ACTION COMPLETE')}</span><h2>${tr('Action complete')}</h2><p>${bg.lastResult}</p><button class="primary-button" data-bg="end-turn">${tr('End turn')} →</button>`;
    }
    if (!space) return `<p>${tr('Choose an action to continue.')}</p>`;
    const head = `<span class="eyebrow">${tr('You landed on')} · ${tr(space.name)}</span><h2>${space.icon} ${tr(space.name)}</h2>`;
    if (space.type === 'start') {
      return `${head}<p>${tr('You completed a lap and received the start bonus.')}</p><button class="primary-button" data-bg="start-continue">${tr('Continue')}</button>`;
    }
    if (space.type === 'property') {
      const owner = bgPropertyOwner(bg.pendingSpace);
      if (!owner) {
        const canBuy = bgCardCount(bgPlayer(), space.career) >= 2;
        return `${head}<p>${tr('Choose an action to continue.')}</p><div class="bg-action-buttons"><button class="primary-button" data-bg="property-draw">${tr('Draw 2 cards')}</button><button class="secondary-button" data-bg="property-buy" ${canBuy ? '' : 'disabled'}>${tr('Trade 2 matching cards and claim this property')}</button><button class="secondary-button" data-bg="pass">${tr('Pass this space')}</button></div>${canBuy ? '' : `<small>${tr('You need two cards from this career to claim it.')} (${tr(space.career)})</small>`}`;
      }
      if (owner.human) return `${head}<p>${tr('This property belongs to you. Collect a small bonus.')}</p><button class="primary-button" data-bg="property-bonus">${tr('Collect your property bonus')}</button>`;
      return `${head}<p>${tr('Owned by')} ${tr(owner.name)}. ${tr('Pay one card from this career to the owner, or pass.')}</p><div class="bg-action-buttons"><button class="primary-button" data-bg="property-rent">${tr('Pay 1 matching card to the owner')}</button><button class="secondary-button" data-bg="pass">${tr('Pass this space')}</button></div>`;
    }
    if (space.type === 'individual') {
      const targets = bgPlayer().missionTargets;
      const matches = bgPlayer().cards.filter(c => targets.includes(c.name));
      return `${head}<p>${tr('Choose a card matching at least one character on your mission card.')}</p><div class="bg-mission-targets">${tr('Your mission characters:')} <b>${targets.join(' · ')}</b></div>${matches.length ? `<div class="bg-action-buttons">${matches.map(c => `<button class="primary-button" data-bg="mission-card" data-card="${c.id}">${c.name} · ✦ ${c.value}</button>`).join('')}</div>` : `<p>${tr('You do not have a matching card yet. Draw a card or pass.')}</p><button class="primary-button" data-bg="mission-draw">${tr('Draw a card')}</button>`}<button class="secondary-button" data-bg="pass">${tr('Pass this space')}</button>`;
    }
    if (space.type === 'powerset') {
      const available = BG_SUBSETS.filter(s => !bg.powerSetChoices.some(x => x.subset === s));
      const options = available.map(s => `<button class="bg-subset-choice" data-bg="powerset" data-subset="${s}">${s}</button>`).join('');
      return `${head}<p>${tr('Choose a subset that has not been selected by another player.')}</p><small>${tr('Available subsets')}: ${available.join(' · ') || tr('All distinct subsets are collected. The power set is complete!')}</small><div class="bg-action-buttons">${options}</div><button class="secondary-button" data-bg="pass">${tr('Pass this space')}</button>`;
    }
    if (space.type === 'cardinality') {
      return `${head}<p>${tr('Situation: 5 cards belong to A, 4 belong to B, and 2 belong to both.')}</p><div class="bg-formula">|A ∪ B| = |A| + |B| − |A ∩ B|</div><p>${tr('How many cards belong to A union B?')}</p>${bg.lastResult ? `<p class="bg-inline-feedback">${bg.lastResult}</p>` : ''}<div class="bg-action-buttons">${[5,7,9,11].map(n => `<button class="bg-answer" data-bg="cardinality" data-answer="${n}">${n}</button>`).join('')}</div>`;
    }
    if (space.type === 'election') {
      return `${head}<p>${tr('Choose the operation on the two collections. You receive the cards in its result.')}</p><div class="bg-sets-preview"><span>A = {Mina, Omid, Nika}</span><span>B = {Omid, Kian}</span></div><div class="bg-action-buttons"><button class="bg-answer" data-bg="election" data-operation="union">${tr('Union')} ∪</button><button class="bg-answer" data-bg="election" data-operation="intersection">${tr('Intersection')} ∩</button><button class="bg-answer" data-bg="election" data-operation="difference">${tr('Difference A − B')} −</button><button class="bg-answer" data-bg="election" data-operation="complement">${tr('Complement of A')} ′</button></div>`;
    }
    return `${head}<p>${tr('Take a quiet moment. You receive 5 points.')}</p><button class="primary-button" data-bg="rest">${tr('Collect rest bonus')}</button>`;
  }

  function finishBoardAction(message) {
    boardGameState.lastResult = message;
    boardGameState.phase = 'end';
    bgLog(message);
    bgSave();
    renderBoardGame();
  }

  function rollBoardDice() {
    if (boardGameState.phase !== 'roll') return;
    const player = bgPlayer();
    const roll = 1 + Math.floor(Math.random() * 6);
    const old = player.position;
    const next = (old + roll) % BG_SPACES.length;
    const passedStart = old + roll >= BG_SPACES.length;
    player.position = next;
    if (passedStart) player.points += 10;
    boardGameState.lastRoll = roll;
    boardGameState.lastResult = '';
    boardGameState.pendingSpace = next;
    boardGameState.phase = 'action';
    const space = BG_SPACES[next];
    bgLog(`${tr('You rolled')} ${roll}. ${tr('You landed on')} ${tr(space.name)}.${passedStart ? ' ' + tr('You passed Start and earned 10 points.') : ''}`);
    bgSave();
    renderBoardGame();
  }

  function handleBoardGameAction(button) {
    const action = button.dataset.bg;
    const player = bgPlayer();
    const spaceIndex = boardGameState.pendingSpace;
    const space = BG_SPACES[spaceIndex];
    if (action === 'roll') return rollBoardDice();
    if (action === 'new') {
      boardGameState = createBoardGame();
      bgSave();
      renderBoardGame();
      return;
    }
    if (action === 'end-turn') return endBoardTurn();
    if (action === 'pass') return finishBoardAction(tr('You passed this space.'));
    if (action === 'start-continue') return finishBoardAction(tr('You completed a lap and received the start bonus.'));
    if (action === 'property-draw') {
      const drawn = bgDrawCards(player, space.career, 2);
      player.points += 5;
      return finishBoardAction(`${tr('You gained')} ${drawn} ${tr(space.career)} ${tr('cards')} and 5 ${tr('points')}.`);
    }
    if (action === 'property-buy') {
      let paid = 0;
      player.cards = player.cards.filter(card => {
        if (card.career === space.career && paid < 2) { paid++; return false; }
        return true;
      });
      if (paid === 2) {
        boardGameState.properties[spaceIndex] = 0;
        player.points += 18;
        return finishBoardAction(`${tr('The property is yours now.')} +18 ${tr('points')}.`);
      }
      return renderBoardGame();
    }
    if (action === 'property-rent') {
      const index = player.cards.findIndex(card => card.career === space.career);
      if (index >= 0) {
        const [paidCard] = player.cards.splice(index, 1);
        const owner = boardGameState.players[boardGameState.properties[spaceIndex]];
        if (bgAddCard(owner, paidCard)) owner.points += paidCard.value;
        return finishBoardAction(tr('You paid a card to the property owner.'));
      }
      player.points = Math.max(0, player.points - 5);
      return finishBoardAction(tr('You could not pay a matching card and lost 5 points.'));
    }
    if (action === 'property-bonus') {
      player.points += 8;
      return finishBoardAction(`${tr('You received the property bonus.')} +8 ${tr('points')}.`);
    }
    if (action === 'mission-draw') {
      const drawn = bgDrawCards(player, null, 1);
      return finishBoardAction(drawn ? tr('A card was added to your hand.') : tr('You already have every available character card.'));
    }
    if (action === 'mission-card') {
      const cardId = Number(button.dataset.card);
      const index = player.cards.findIndex(card => card.id === cardId);
      if (index < 0) return;
      const card = player.cards[index];
      if (!player.missionTargets.includes(card.name)) return;
      player.cards.splice(index, 1);
      const reward = card.value * 2;
      player.points += reward;
      player.missions++;
      player.missionTargets = ['Tara', 'Arman'];
      return finishBoardAction(`${tr('You completed the mission and earned double card value.')} +${reward} ${tr('points')}.`);
    }
    if (action === 'powerset') {
      const subset = button.dataset.subset;
      if (boardGameState.powerSetChoices.some(x => x.subset === subset)) return;
      boardGameState.powerSetChoices.push({ subset, playerId: 0 });
      player.points += 12;
      for (let bot = 1; bot <= 2 && boardGameState.powerSetChoices.length < BG_SUBSETS.length; bot++) {
        const choices = BG_SUBSETS.filter(s => !boardGameState.powerSetChoices.some(x => x.subset === s));
        if (choices.length) {
          const botSubset = choices[Math.floor(Math.random() * choices.length)];
          boardGameState.powerSetChoices.push({ subset: botSubset, playerId: bot });
          boardGameState.players[bot].points += 8;
        }
      }
      if (boardGameState.powerSetChoices.length === BG_SUBSETS.length) {
        player.points += 20;
        boardGameState.powerSetChoices = [];
        return finishBoardAction(`${tr('All distinct subsets are collected. The power set is complete!')} +32 ${tr('points')}.`);
      }
      return finishBoardAction(`${tr('You gained')} 12 ${tr('points')}. ${tr('Your subset')} ${subset} ${tr('was recorded')}.`);
    }
    if (action === 'cardinality') {
      if (Number(button.dataset.answer) === 7) {
        player.points += 20;
        player.missions++;
        return finishBoardAction(`${tr('Correct!')} 5 + 4 − 2 = 7. +20 ${tr('points')}.`);
      }
      player.points = Math.max(0, player.points - 2);
      boardGameState.lastResult = tr('Not quite. Use the union formula and try again.') + ' (5 + 4 − 2 = 7)';
      bgLog(boardGameState.lastResult);
      bgSave();
      renderBoardGame();
      return;
    }
    if (action === 'election') {
      const A = ['Mina', 'Omid', 'Nika'];
      const B = ['Omid', 'Kian'];
      const U = ['Mina', 'Omid', 'Nika', 'Kian', 'Laleh', 'Tara'];
      const operation = button.dataset.operation;
      let result = [];
      if (operation === 'union') result = [...new Set([...A, ...B])];
      if (operation === 'intersection') result = A.filter(x => B.includes(x));
      if (operation === 'difference') result = A.filter(x => !B.includes(x));
      if (operation === 'complement') result = U.filter(x => !A.includes(x));
      const added = [];
      result.forEach(name => {
        const card = BG_CARD_DECK.find(c => c.name === name);
        if (card && bgAddCard(player, card)) added.push(name);
      });
      player.points += added.length * 3;
      return finishBoardAction(`${tr('The election result was added to your hand.')} ${tr('Result')}: {${result.join(', ')}} · ${tr('New cards')}: ${added.length} · +${added.length * 3} ${tr('points')}.`);
    }
    if (action === 'rest') {
      player.points += 5;
      return finishBoardAction(`${tr('You received the property bonus.')} +5 ${tr('points')}.`);
    }
  }

  function endBoardTurn() {
    if (boardGameState.phase !== 'end') return;
    boardGameState.phase = 'bots';
    renderBoardGame();
    for (let i = 1; i < boardGameState.players.length; i++) {
      const bot = boardGameState.players[i];
      const roll = 1 + Math.floor(Math.random() * 6);
      const passedStart = bot.position + roll >= BG_SPACES.length;
      bot.position = (bot.position + roll) % BG_SPACES.length;
      if (passedStart) bot.points += 10;
      const landed = BG_SPACES[bot.position];
      if (landed.type === 'property' && boardGameState.properties[bot.position] === undefined) {
        boardGameState.properties[bot.position] = i;
        bot.points += 8;
      } else if (landed.type === 'individual' || landed.type === 'cardinality') {
        bot.points += 10;
        bot.missions++;
      } else if (landed.type === 'powerset') {
        const available = BG_SUBSETS.filter(s => !boardGameState.powerSetChoices.some(x => x.subset === s));
        if (available.length) {
          boardGameState.powerSetChoices.push({ subset: available[0], playerId: i });
          bot.points += 8;
          if (boardGameState.powerSetChoices.length === BG_SUBSETS.length) {
            boardGameState.powerSetChoices = [];
            bgLog(tr('The bots completed a full power set round.'));
          }
        }
      } else if (landed.type === 'election') bot.points += 9;
      else bot.points += 5;
      bgDrawCards(bot, null, 1);
      bgLog(`${tr(bot.name)} rolled ${roll}, landed on ${tr(landed.name)} and gained points.`);
    }
    boardGameState.round++;
    if (boardGameState.round > boardGameState.maxRounds) return finishBoardMatch();
    boardGameState.pendingSpace = null;
    boardGameState.lastRoll = null;
    boardGameState.phase = 'roll';
    bgSave();
    renderBoardGame();
  }

  function finishBoardMatch() {
    const sorted = [...boardGameState.players].sort((a, b) => b.points - a.points);
    const winner = sorted[0];
    const human = bgPlayer();
    const award = 30 + (winner.human ? 30 : 0) + Math.min(20, Math.floor(human.points / 20));
    if (!boardGameState.xpAwarded) {
      state.xp += award;
      boardGameState.xpAwarded = true;
      saveState();
    }
    const result = winner.human ? `${tr('You won the match!')} ${tr('You earned')} ${award} XP.` : `${tr('You finished the match.')} ${tr('The winner was')} ${tr(winner.name)}. ${tr('You earned')} ${award} XP.`;
    boardGameState.lastResult = result;
    boardGameState.phase = 'finished';
    boardGameState.finished = true;
    bgLog(result);
    bgSave();
    render();
    renderBoardGame();
  }

  function renderLearn() {
    const units = [
      { title: 'Set and elements', body: 'A set is a well-defined collection of distinct objects. Each object is called an element. Repeated objects are written only once.', formula: 'A = {1, 2, 3} · 2 ∈ A · 5 ∉ A', example: 'A = {1, 2, 3}, B = {1, 3} so B ⊆ A.', question: 'Which option is a set with no repeated elements?', options: ['{1, 1, 2}', '{a, b, c}', '{2, 3, 2, 3}'], answer: 1 },
      { title: 'Subset and equality', body: 'If every element of B is also an element of A, then B is a subset of A. Two sets are equal when they contain exactly the same elements.', formula: 'B ⊆ A · (A ⊆ B and B ⊆ A) ⇒ A = B', example: 'A = {1, 2, 3}, B = {1, 3}. Therefore B is a subset of A.', question: 'If A = {1, 2, 3} and B = {1, 3}, which statement is true?', options: ['A ⊆ B', 'B ⊆ A', 'A = B'], answer: 1 },
      { title: 'Power set', body: 'The power set is the set of all subsets of a set, including the empty set and the set itself. A set with n elements has 2ⁿ subsets.', formula: 'P(A) = {∅, {a}, {b}, {a, b}} · |P(A)| = 2ⁿ', example: 'If A = {a, b}, then P(A) has four members: ∅, {a}, {b}, and {a, b}.', question: 'How many subsets does a set with 3 elements have?', options: ['3', '6', '8'], answer: 2 },
      { title: 'Operations on sets', body: 'Union contains elements in A or B or both. Intersection contains only shared elements. Difference A minus B contains elements in A that are not in B. The complement contains elements outside A in the universal set.', formula: 'A ∪ B · A ∩ B · A − B · A′', example: 'For A = {1, 2, 3} and B = {3, 4}, A∪B = {1, 2, 3, 4} and A∩B = {3}.', question: 'For A = {1, 2, 3} and B = {3, 4}, what is A∩B?', options: ['{1, 2, 3, 4}', '{3}', '{1, 2}'], answer: 1 },
      { title: 'Cardinality and Venn diagrams', body: 'Cardinality is the number of elements in a set. In a Venn diagram, the overlap is counted once. For two finite sets, |A∪B| = |A| + |B| − |A∩B|.', formula: '|A ∪ B| = |A| + |B| − |A ∩ B|', example: 'If |A| = 5, |B| = 4 and |A∩B| = 2, then |A∪B| = 7.', question: 'If A has 5 elements, B has 4, and the intersection has 2, how many elements are in the union?', options: ['9', '7', '11'], answer: 1 }
    ];
    const unit = units[lessonIndex];
    $('lessonNav').innerHTML = `<span class="eyebrow">${tr('Choose a topic')}</span>` + units.map((u, i) => `<button class="lesson-nav-item ${lessonIndex === i ? 'active' : ''}" data-lesson="${i}"><span>${String(i + 1).padStart(2, '0')}</span>${tr(u.title)}</button>`).join('');
    $('lessonContent').innerHTML = `<span class="eyebrow">${tr('Lesson')} ${lessonIndex + 1} / 5</span><h2>${tr(unit.title)}</h2><p class="lesson-description">${tr(unit.body)}</p><div class="lesson-formula">${tr(unit.formula)}</div><h3>${tr('Example')}</h3><div class="lesson-example">${tr(unit.example)}</div><div class="lesson-quiz"><span class="eyebrow">${tr('Quick check')}</span><h3>${tr(unit.question)}</h3><div class="lesson-options">${unit.options.map((op, i) => `<button class="lesson-option" data-lesson-answer="${i}">${tr(op)}</button>`).join('')}</div><p id="lessonFeedback" aria-live="polite"></p><button class="primary-button" id="lessonCheck" disabled>${tr('Check my answer')}</button></div><div class="lesson-navigation"><button class="secondary-button" data-lesson-prev ${lessonIndex === 0 ? 'disabled' : ''}>← ${tr('Back to previous topic')}</button><button class="secondary-button" data-lesson-next ${lessonIndex === units.length - 1 ? 'disabled' : ''}>${tr('Next topic')} →</button></div>`;
    selectedLessonAnswer = null;
  }

  function checkLessonAnswer() {
    const unitsCorrect = [1, 1, 2, 1, 1];
    const feedback = $('lessonFeedback');
    const isCorrect = selectedLessonAnswer === unitsCorrect[lessonIndex];
    feedback.textContent = isCorrect ? tr('Correct answer. Well done!') : tr('Not quite. Read the example and try once more.');
    feedback.className = isCorrect ? 'lesson-feedback success' : 'lesson-feedback error';
    if (isCorrect) {
      const lessonKey = `lesson-${lessonIndex}`;
      state.learnedLessons = Array.isArray(state.learnedLessons) ? state.learnedLessons : [];
      if (!state.learnedLessons.includes(lessonKey)) {
        state.learnedLessons.push(lessonKey);
        state.xp += 10;
        saveState();
        render();
        feedback.textContent += ` +10 XP`;
      }
    }
  }

  function handleLearningClick(event) {
    const lessonButton = event.target.closest('[data-lesson]');
    const answerButton = event.target.closest('[data-lesson-answer]');
    const checkButton = event.target.closest('#lessonCheck');
    const prevButton = event.target.closest('[data-lesson-prev]');
    const nextButton = event.target.closest('[data-lesson-next]');
    if (lessonButton) {
      lessonIndex = Number(lessonButton.dataset.lesson);
      renderLearn();
    } else if (answerButton) {
      selectedLessonAnswer = Number(answerButton.dataset.lessonAnswer);
      document.querySelectorAll('.lesson-option').forEach(b => b.classList.toggle('selected', Number(b.dataset.lessonAnswer) === selectedLessonAnswer));
      $('lessonCheck').disabled = false;
    } else if (checkButton) checkLessonAnswer();
    else if (prevButton && lessonIndex > 0) { lessonIndex--; renderLearn(); }
    else if (nextButton && lessonIndex < 4) { lessonIndex++; renderLearn(); }
  }

